'use strict';

// MODULES //

var tape = require( 'tape' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var Float32Array = require( '@stdlib/array/float32' );
var ndarray = require( '@stdlib/ndarray/base/ctor' );
var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
var snanvariance = require( './../lib' );


// FUNCTIONS //

/**
* Returns a one-dimensional ndarray.
*
* @private
* @param {Collection} buffer - underlying data buffer
* @param {NonNegativeInteger} length - number of indexed elements
* @param {integer} stride - stride length
* @param {NonNegativeInteger} offset - index offset
* @returns {ndarray} one-dimensional ndarray
*/
function vector( buffer, length, stride, offset ) {
	return new ndarray( 'float32', buffer, [ length ], [ stride ], offset, 'row-major' );
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof snanvariance, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 1', function test( t ) {
	t.strictEqual( snanvariance.length, 1, 'has expected arity' );
	t.end();
});

tape( 'the function computes the sample variance of a one-dimensional ndarray', function test( t ) {
	var c;
	var x;
	var v;

	c = scalar2ndarray( 1.0, {
		'dtype': 'float32'
	});

	// [1, 2, 3] → variance = 1
	x = new Float32Array( [ 1.0, 2.0, 3.0 ] );
	v = snanvariance( [ vector( x, 3, 1, 0 ), c ] );
	t.strictEqual( v, 1.0, 'returns expected value' );

	// [-4, -5] → variance = 0.5
	x = new Float32Array( [ -4.0, -5.0 ] );
	v = snanvariance( [ vector( x, 2, 1, 0 ), c ] );
	t.strictEqual( v, 0.5, 'returns expected value' );

	t.end();
});

tape( 'the function ignores NaN values', function test( t ) {
	var c;
	var x;
	var v;

	c = scalar2ndarray( 1.0, {
		'dtype': 'float32'
	});

	// [1, NaN, 2, 3] → [1,2,3]
	x = new Float32Array( [ 1.0, NaN, 2.0, 3.0 ] );
	v = snanvariance( [ vector( x, 4, 1, 0 ), c ] );
	t.strictEqual( v, 1.0, 'returns expected value' );

	t.end();
});

tape( 'the function returns NaN if insufficient non-NaN values are available', function test( t ) {
	var c;
	var x;
	var v;

	c = scalar2ndarray( 1.0, {
		'dtype': 'float32'
	});

	x = new Float32Array( [ 2.0 ] );
	v = snanvariance( [ vector( x, 1, 1, 0 ), c ] );
	t.strictEqual( isnanf( v ), true, 'returns NaN' );

	x = new Float32Array( [ NaN, NaN ] );
	v = snanvariance( [ vector( x, 2, 1, 0 ), c ] );
	t.strictEqual( isnanf( v ), true, 'returns NaN' );

	t.end();
});

tape( 'the function supports one-dimensional ndarrays with non-unit strides', function test( t ) {
	var c;
	var x;
	var v;

	c = scalar2ndarray( 1.0, {
		'dtype': 'float32'
	});

	// Values accessed: [1, 2, 3]
	x = new Float32Array([
		1.0,  // 0
		0.0,
		2.0,  // 1
		0.0,
		3.0,  // 2
		0.0
	]);

	v = snanvariance( [ vector( x, 3, 2, 0 ), c ] );
	t.strictEqual( v, 1.0, 'returns expected value' );

	t.end();
});

tape( 'the function supports one-dimensional ndarrays with negative strides', function test( t ) {
	var c;
	var x;
	var v;

	c = scalar2ndarray( 1.0, {
		'dtype': 'float32'
	});

	// Values accessed (reverse): [1,2,3]
	x = new Float32Array([
		3.0,  // 2
		0.0,
		2.0,  // 1
		0.0,
		1.0,  // 0
		0.0
	]);

	v = snanvariance( [ vector( x, 3, -2, 4 ), c ] );
	t.strictEqual( v, 1.0, 'returns expected value' );

	t.end();
});

tape( 'the function supports one-dimensional ndarrays with non-zero offsets', function test( t ) {
	var c;
	var x;
	var v;

	c = scalar2ndarray( 1.0, {
		'dtype': 'float32'
	});

	// Values accessed: [1,2,3]
	x = new Float32Array([
		0.0,
		1.0,  // 0
		0.0,
		2.0,  // 1
		0.0,
		3.0   // 2
	]);

	v = snanvariance( [ vector( x, 3, 2, 1 ), c ] );
	t.strictEqual( v, 1.0, 'returns expected value' );

	t.end();
});
